import React, { useRef, useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Upload,
  FileVideo,
  Sparkles,
  FolderOpen,
  Trash2,
  X,
  Send,
} from "lucide-react";

export default function UploadArea({
  uploadedFiles,
  setUploadedFiles,
  isAnalyzing,
  setIsAnalyzing,
  setAnalysisResults,
  setDetectedFrames,
  setShowAnalysis,
}) {
  const fileInputRef = useRef(null);
  const folderInputRef = useRef(null);
  const [userQuery, setUserQuery] = useState("");

  // ===============================
  // ⭐ Upload to Backend
  // ===============================
  const uploadToBackend = async () => {
    if (!uploadedFiles.length) {
      console.warn("No files to upload");
      return;
    }

    const form = new FormData();

    // Check if folder upload
    const folderName = uploadedFiles[0].folderName || "";

    uploadedFiles.forEach((fileObj) => {
      form.append("files", fileObj.file); // REAL FILE OBJECT
    });

    if (folderName) {
      form.append("folderName", folderName);
    }

    try {
      const res = await fetch("http://localhost:5000/api/upload", {
        method: "POST",
        body: form,
      });

      const data = await res.json();
      console.log("UPLOAD RESPONSE:", data);

      if (!data.success) {
        alert("Upload failed!");
      } else {
        alert("Uploaded successfully!");
      }
    } catch (err) {
      console.error("Upload error:", err);
      alert("Upload failed");
    }
  };

  // ===============================
  // ⭐ Upload files & Run AI
  // ===============================
  const analyzeFolder = async () => {
  if (!uploadedFiles.length) return;

  setIsAnalyzing(true);  // SHOW ANIMATION

  await uploadToBackend();

  // Simulate backend processing delay (optional)
  // await new Promise((res) => setTimeout(res, 1200));

  setIsAnalyzing(false);  // HIDE ANIMATION

  setShowAnalysis(true);  // NAVIGATE TO ANALYSIS PAGE
};


  // ===============================
  // ⭐ File Input
  // ===============================
  const handleFileChange = (event) => {
    const files = Array.from(event.target.files || []);

    const videoFiles = files.map((file) => ({
      file, // REAL file object
      name: file.name,
      size: file.size,
      type: file.type,
      path: URL.createObjectURL(file),
    }));

    setUploadedFiles((prev) => [...prev, ...videoFiles]);
    event.target.value = "";
  };

  // ===============================
  // ⭐ Folder Input
  // ===============================
  const handleFolderChange = (event) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;

    // Extract folder name from webkitRelativePath
    const firstPath = files[0].webkitRelativePath;
    const folderName = firstPath.split("/")[0];

    const videoFiles = files
      .filter((file) => file.type.startsWith("video/"))
      .map((file) => ({
        file, // REAL file
        name: file.name,
        size: file.size,
        type: file.type,
        path: URL.createObjectURL(file),
        folderName, // IMPORTANT
      }));

    setUploadedFiles(videoFiles);
    event.target.value = "";
  };

  // ===============================
  // ⭐ Delete / Clear
  // ===============================
  const deleteFile = (index) => {
    setUploadedFiles((prev) => {
      const newFiles = [...prev];
      URL.revokeObjectURL(newFiles[index].path);
      newFiles.splice(index, 1);
      return newFiles;
    });
  };

  const clearAllFiles = () => {
    uploadedFiles.forEach((file) => URL.revokeObjectURL(file.path));
    setUploadedFiles([]);
  };

  const formatFileSize = (bytes) => {
    const sizes = ["Bytes", "KB", "MB", "GB"];
    let i = Math.floor(Math.log(bytes) / Math.log(1024));
    return (bytes / Math.pow(1024, i)).toFixed(2) + " " + sizes[i];
  };

  return (
    <div className="upload-center">
      <Card className="upload-card">
        <div className="upload-card-inner">
          <div className="upload-drop-box">
            <div className="upload-drop-header">
              <div className="upload-icon-circle">
                <Upload className="upload-main-icon" />
              </div>

              <div className="upload-text-block">
                <h3 className="upload-main-heading">
                  Drop NSG surveillance files or folders here
                </h3>
                <p className="upload-main-text">
                  Supports MP4, AVI, MOV and other common video streams.
                </p>
              </div>
            </div>

            <div className="upload-actions upload-actions-top">
              <Button className="primary-btn" onClick={() => fileInputRef.current.click()}>
                <FileVideo className="icon-sm icon-left" />
                Upload File
              </Button>

              <Button className="primary-btn" onClick={() => folderInputRef.current.click()}>
                <FolderOpen className="icon-sm icon-left" />
                Upload Folder
              </Button>

              {uploadedFiles.length > 0 && (
                <Button
                  onClick={analyzeFolder}
                  disabled={isAnalyzing}
                  className="danger-btn"
                >
                  <Sparkles className="icon-sm icon-left" />
                  {isAnalyzing ? "Uploading..." : "Run AI Analysis"}
                </Button>
              )}
            </div>
          </div>

          {/* FILE LIST */}
          {uploadedFiles.length > 0 && (
            <div className="upload-status">
              <div className="upload-status-header">
                <div className="upload-status-left">
                  <FolderOpen className="icon-sm tactical-colour" />
                  <p className="upload-status-text">
                    {uploadedFiles.length} videos selected
                  </p>
                </div>

                <Button
                  variant="ghost"
                  size="sm"
                  onClick={clearAllFiles}
                  className="icon-circle danger-icon"
                >
                  <Trash2 className="icon-xs" />
                </Button>
              </div>

              <div className="upload-status-list">
                {uploadedFiles.map((file, index) => (
                  <div key={index} className="upload-file-row">
                    <div className="upload-file-left">
                      <FileVideo className="icon-xs muted-colour" />
                      <span className="upload-file-name">{file.name}</span>
                    </div>

                    <div className="upload-file-right">
                      <span className="upload-file-size">
                        {formatFileSize(file.size)}
                      </span>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => deleteFile(index)}
                        className="icon-circle subtle-delete"
                      >
                        <X className="icon-xs" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Hidden file inputs */}
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="video/*"
            multiple
            className="hidden-input"
          />

          <input
            type="file"
            ref={folderInputRef}
            onChange={handleFolderChange}
            accept="video/*"
            multiple
            webkitdirectory="true"
            className="hidden-input"
          />
        </div>
      </Card>
    </div>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { FileVideo, Clock, Download } from "lucide-react";
import useLiveAnalysis from "./useLiveAnalysis";
import "./videoAnalysisCard.css";

export default function VideoAnalysisCard({ result, detectedFrames }) {
  // 🔥 LIVE DATA FROM SOCKET
  const { liveVideoInfo, liveFrames } = useLiveAnalysis();

  // Filter frames for this specific video
  const framesForVideo = (detectedFrames || []).filter(
    (frame) => frame.videoName === result.fileName
  );

  // PDF Download
  const handleDownloadPDF = () => {
    const pdfContent = `
NSG AI Video Analysis Report
Generated: ${new Date().toLocaleString()}

FILE: ${result.fileName}
Duration: ${result.duration}
Threat Level: ${result.threatLevel.toUpperCase()}
Confidence: ${result.confidence}%

TIMELINE:
${result.timeline.map((item) => `${item.time} - ${item.event}`).join("\n")}

SUMMARY:
${result.summary}

CONCLUSION:
${getConclusionText(result)}
`;

    const blob = new Blob([pdfContent], { type: "application/pdf" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = `analysis-${result.fileName}-${Date.now()}.pdf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const threatScore =
    result.threatLevel === "high"
      ? 90
      : result.threatLevel === "medium"
      ? 65
      : 22;

  const validFrames =
    result.keyFrames && Array.isArray(result.keyFrames)
      ? result.keyFrames
      : [];

  return (
    <Card className="analysis-result-card">

      {/* ----------------------------------------------------- */}
      {/* 🔵 LIVE ANALYSIS BANNER */}
      {/* ----------------------------------------------------- */}
      {liveVideoInfo && (
        <div className="live-banner">
          <h3>🔵 Live Analysis Running...</h3>
          <p><b>Video:</b>Video Name</p>
          <p><b>Duration:</b> 20:09</p>
        </div>
      )}

      {/* ----------------------------------------------------- */}
      {/* 🔵 REAL-TIME FRAME GRID */}
      {/* ----------------------------------------------------- */}
      {liveFrames.length > 0 && (
        <div className="live-frame-section">
          <h4>Real-Time Detected Frames ({liveFrames.length})</h4>

          <div className="live-frame-grid">
            {liveFrames.map((frame, i) => (
              <div className="live-frame-card" key={i}>
                <img src={frame.imageUrl} className="live-frame-thumb" alt="live" />
                <p className="live-frame-meta">
                  <b>{frame.timestamp}</b> – {frame.shortSummary}
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ----------------------------------------------------- */}
      {/* HEADER */}
      {/* ----------------------------------------------------- */}
      <div className="analysis-result-header">
        <div className="analysis-result-left">
          <FileVideo className="icon-sm tactical-colour" />
          <div>
            <h3 className="analysis-result-title">{result.fileName}</h3>
            <p className="analysis-result-subtitle">Automated Tactical Intelligence Summary</p>
          </div>
        </div>

        <div className="analysis-result-meta">
          <div
            className={
              result.threatLevel === "high"
                ? "pill pill-danger"
                : result.threatLevel === "medium"
                ? "pill pill-warning"
                : "pill pill-success"
            }
          >
            {result.threatLevel.toUpperCase()} THREAT
          </div>

          <span className="analysis-confidence">Confidence: {result.confidence}%</span>

          <Button size="sm" className="primary-btn report-btn" onClick={handleDownloadPDF}>
            <Download className="icon-sm icon-left" />
            Download PDF
          </Button>
        </div>
      </div>

      {/* ----------------------------------------------------- */}
      {/* 2-COLUMN GRID LAYOUT */}
      {/* ----------------------------------------------------- */}
      <div className="analysis-result-body">

        {/* ================= LEFT COLUMN — TIMELINE ================= */}
        <div className="analysis-column">
          {/* TIMELINE SECTION */}
          <div className="analysis-section">
            <h4 className="section-title">Event Timeline</h4>
            <div className="timeline-list">
              {result.timeline.map((event, i) => (
                <div key={i} className="timeline-row">
                  <span className="timeline-time">{event.time}</span>
                  <span className="timeline-event">{event.event}</span>
                </div>
              ))}
            </div>
          </div>

          {/* DURATION SECTION */}
          <div className="analysis-section">
            <h4 className="section-title">Video Duration</h4>
            <div className="duration-row">
              <Clock className="icon-xs tactical-colour" />
              <span className="duration-text">{result.duration}</span>
            </div>
          </div>
        </div>

        {/* ================= RIGHT COLUMN — IMAGES GRID ================= */}
        <div className="analysis-column">
          {/* SNAPSHOTS GRID */}
          <div className="snapshot-card">
            <div className="snapshot-card-header">
              <h4 className="section-title">Key Moment Snapshots</h4>
              <span className="snapshot-count">{validFrames.length} frames</span>
            </div>

            <div className="snapshot-frames-container">
              {validFrames.length ? (
                validFrames.map((frame, i) => {
                  const frameSrc = typeof frame === "string" ? frame : (frame.src || frame.url || frame.image);
                  const frameTime = typeof frame === "object" ? (frame.time || frame.timestamp || result.duration) : result.duration;
                  
                  return (
                    <div className="snapshot-frame" key={i}>
                      <div className="snapshot-frame-image-wrapper">
                        {frameSrc ? (
                          <img
                            src={frameSrc}
                            className="snapshot-frame-image"
                            alt={`Key frame ${i + 1}`}
                          />
                        ) : (
                          <div style={{ 
                            display: 'flex', 
                            alignItems: 'center', 
                            justifyContent: 'center',
                            height: '100%',
                            color: '#6b7280',
                            fontSize: '0.8rem'
                          }}>
                            No Image
                          </div>
                        )}
                      </div>
                      <div className="snapshot-frame-meta">
                        <span className="snapshot-frame-label">Frame {i + 1}</span>
                        <span className="snapshot-frame-time">{frameTime}</span>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="snapshot-empty">
                  No snapshots available for this video.
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* ----------------------------------------------------- */}
      {/* SUMMARY PANEL */}
      {/* ----------------------------------------------------- */}
      <div className="summary-panel">
        <h4 className="section-title">Summary Report</h4>

        <div className="summary-section">
          <h5 className="summary-subtitle">Detailed Narrative</h5>
          <p className="summary-text">{result.summary}</p>
        </div>

        <div className="summary-section summary-conclusion">
          <h5 className="summary-subtitle">Conclusion</h5>
          <p className="summary-text">{getConclusionText(result)}</p>
        </div>
      </div>

    </Card>
  );
}

function getConclusionText(result) {
  if (result.threatLevel === "high")
    return "High-risk activity detected. Immediate review recommended.";
  if (result.threatLevel === "medium")
    return "Moderate risk indicators present. Requires secondary confirmation.";
  return "No significant anomalies detected. Footage appears normal.";
}



