    fill="none"
    stroke="currentColor"
  >
    <path
      d="M7 4h7l5 5v11H7z"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    <path
      d="M14 4v5h5"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    <path
      d="M10 13h4M10 16h2"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const EvidenceIcon = () => (
  <svg
    className="menu-icon"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
  >
    <rect
      x="4"
      y="5"
      width="16"
      height="14"
      rx="2"
      ry="2"
      strokeWidth="1.7"
    />
    <circle cx="12" cy="12" r="3" strokeWidth="1.7" />
    <path
      d="M17 8.5v.01"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const CaseIcon = () => (
  <svg
    className="menu-icon"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
  >
    <rect
      x="3"
      y="7"
      width="18"
      height="12"
      rx="2"
