  <svg
    className="menu-icon"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
  >
    <circle cx="8" cy="9" r="3" strokeWidth="1.7" />
    <circle cx="16" cy="9" r="3" strokeWidth="1.7" />
    <path
      d="M4 19v-1.5A3.5 3.5 0 0 1 7.5 14h1A3.5 3.5 0 0 1 12 17.5V19"
