      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const SettingsIcon = () => (
  <svg
    className="menu-icon"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
  >
